import Darwin
import Foundation
import PicShotTextScriptCore

/// Native gate target only. Never part of the product helper or JavaScript API.
/// Every request is generated by the gate and uses real stdin/stdout transport.
@main
enum TextScriptTransportFixtureMain {
    static func main() {
        alarm(5)
        signal(SIGPIPE, SIG_IGN)
        guard CommandLine.arguments.count == 2 else { exit(64) }
        let mode = CommandLine.arguments[1]
        var requestBytes = Data()
        while true {
            var buffer = [UInt8](repeating: 0, count: 4096)
            let count = Darwin.read(STDIN_FILENO, &buffer, buffer.count)
            if count < 0, errno == EINTR { continue }
            guard count >= 0, requestBytes.count + count <= TextScriptLimits.requestBytes else { exit(65) }
            if count == 0 { break }
            requestBytes.append(contentsOf: buffer.prefix(count))
        }
        guard let request = try? TextScriptProtocol.decodeRequest(requestBytes) else { exit(65) }
        let valid = TextScriptResponse.success(requestID: request.requestID, output: "generated-fixture-output")
        switch mode {
        case "malformed": emit(Data("{\"invalid\":true}\n".utf8))
        case "missing-newline":
            emit(Data(((try? TextScriptProtocol.encodeResponse(valid)) ?? Data()).dropLast()))
        case "multiple-response":
            let frame = (try? TextScriptProtocol.encodeResponse(valid)) ?? Data()
            emit(frame); emit(frame)
        case "oversized":
            let chunk = Data(repeating: 65, count: 4096)
            for _ in 0..<80 { emit(chunk) }
        case "wrong-identity":
            emit((try? TextScriptProtocol.encodeResponse(.success(requestID: UUID(), output: "generated-fixture-output"))) ?? Data())
        case "duplicate-key":
            emit(Data(("{\"schemaVersion\":1,\"requestID\":\"" + request.requestID.uuidString + "\",\"status\":\"success\",\"output\":\"x\",\"output\":\"y\"}\n").utf8))
        case "late-response":
            signal(SIGTERM, SIG_IGN)
            usleep(3_150_000)
            emit((try? TextScriptProtocol.encodeResponse(valid)) ?? Data())
        case "ignore-terminate":
            signal(SIGTERM, SIG_IGN)
            while true { pause() }
        case "valid-before-hang":
            emit((try? TextScriptProtocol.encodeResponse(valid)) ?? Data())
            while true { pause() }
        case "stderr-flood":
            let chunk = Data(repeating: 66, count: 4096)
            for _ in 0..<128 { emit(chunk, fd: STDERR_FILENO) }
            emit((try? TextScriptProtocol.encodeResponse(valid)) ?? Data())
        default: exit(64)
        }
    }

    private static func emit(_ data: Data, fd: Int32 = STDOUT_FILENO) {
        var offset = 0
        while offset < data.count {
            let count = data.withUnsafeBytes { Darwin.write(fd, $0.baseAddress!.advanced(by: offset), data.count - offset) }
            if count < 0, errno == EINTR { continue }
            guard count > 0 else { exit(74) }
            offset += count
        }
    }
}
